"use client"

import * as React from "react"
import { flexRender } from "@tanstack/react-table"
import {
  getCoreRowModel,
  getSortedRowModel,
  useLegacyTable,
  type LegacyColumnDef,
} from "@tanstack/react-table/legacy"
import type { RowSelectionState, SortingState } from "@tanstack/react-table"
import {
  ArrowDown,
  ArrowUp,
  ArrowUpDown,
  Columns3,
  Download,
  Search,
} from "lucide-react"
import { toast } from "sonner"

import { cn } from "@/lib/utils"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { Checkbox } from "@/components/ui/checkbox"
import {
  DropdownMenu,
  DropdownMenuCheckboxItem,
  DropdownMenuContent,
  DropdownMenuLabel,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import { Input } from "@/components/ui/input"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import {
  Sheet,
  SheetContent,
  SheetDescription,
  SheetHeader,
  SheetTitle,
} from "@/components/ui/sheet"
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table"
import { downloadCsv, toCsv, type CsvColumn } from "@/lib/csv"
import { EmptyState } from "@/components/ui/entity-form"

export type DataTableTab<T> = {
  id: string
  label: string
  predicate?: (row: T) => boolean
}

export type DataTableFilter<T> = {
  id: string
  label: string
  options: { value: string; label: string }[]
  predicate: (row: T, value: string) => boolean
}

export type DataTableBulkAction<T> = {
  id: string
  label: string
  destructive?: boolean
  onAction: (rows: T[]) => Promise<void> | void
}

export type AdminDataTableProps<T extends { id: string }> = {
  data: readonly T[]
  columns: LegacyColumnDef<T>[]
  tabs?: readonly DataTableTab<T>[]
  filters?: readonly DataTableFilter<T>[]
  searchText?: (row: T) => string
  searchPlaceholder?: string
  bulkActions?: readonly DataTableBulkAction<T>[]
  csvColumns?: readonly CsvColumn[]
  csvFilename?: string
  toCsvRow?: (row: T) => Record<string, unknown>
  renderDetail?: (row: T) => React.ReactNode
  detailTitle?: (row: T) => string
  className?: string
  emptyTitle?: string
  columnsLabel?: string
  csvLabel?: string
  selectedLabel?: string
  previousLabel?: string
  nextLabel?: string
  detailFallback?: string
  detailDescription?: string
  viewsLabel?: string
  selectAllLabel?: string
  selectRowLabel?: string
  actionErrorLabel?: string
}

export function AdminDataTable<T extends { id: string }>({
  data,
  columns,
  tabs,
  filters,
  searchText,
  searchPlaceholder = "Search",
  bulkActions,
  csvColumns,
  csvFilename = "export.csv",
  toCsvRow,
  renderDetail,
  detailTitle,
  className,
  emptyTitle = "No rows",
  columnsLabel = "Columns",
  csvLabel = "CSV",
  selectedLabel = "selected",
  previousLabel = "Previous",
  nextLabel = "Next",
  detailFallback = "Details",
  detailDescription = "Row details",
  viewsLabel = "Views",
  selectAllLabel = "Select all",
  selectRowLabel = "Select row",
  actionErrorLabel = "That action failed",
}: AdminDataTableProps<T>) {
  const [tab, setTab] = React.useState(tabs?.[0]?.id ?? "all")
  const [query, setQuery] = React.useState("")
  const [filterValues, setFilterValues] = React.useState<Record<string, string>>({})
  const [sorting, setSorting] = React.useState<SortingState>([])
  const [columnVisibility, setColumnVisibility] = React.useState<Record<string, boolean>>({})
  const [rowSelection, setRowSelection] = React.useState<RowSelectionState>({})
  const [openId, setOpenId] = React.useState<string | null>(null)
  const [acting, setActing] = React.useState<string | null>(null)

  const searched = React.useMemo(() => {
    const q = query.trim().toLowerCase()
    return data.filter((row) => {
      if (q && searchText && !searchText(row).toLowerCase().includes(q)) return false
      for (const filter of filters ?? []) {
        const value = filterValues[filter.id]
        if (value && value !== "any" && !filter.predicate(row, value)) return false
      }
      return true
    })
  }, [data, filterValues, filters, query, searchText])

  const counts = React.useMemo(() => {
    const map = new Map<string, number>()
    for (const item of tabs ?? []) {
      map.set(
        item.id,
        item.predicate ? searched.filter(item.predicate).length : searched.length,
      )
    }
    return map
  }, [searched, tabs])

  const rows = React.useMemo(() => {
    const current = tabs?.find((item) => item.id === tab)
    if (!current?.predicate) return searched
    return searched.filter(current.predicate)
  }, [searched, tab, tabs])

  const selectionColumn: LegacyColumnDef<T> = {
    id: "select",
    enableSorting: false,
    enableHiding: false,
    header: ({ table }) => (
      <Checkbox
        checked={
          table.getIsAllRowsSelected()
            ? true
            : table.getIsSomeRowsSelected()
              ? "indeterminate"
              : false
        }
        onCheckedChange={(value) => table.toggleAllRowsSelected(value === true)}
        aria-label={selectAllLabel}
      />
    ),
    cell: ({ row }) => (
      <Checkbox
        checked={row.getIsSelected()}
        onCheckedChange={(value) => row.toggleSelected(value === true)}
        aria-label={selectRowLabel}
        onClick={(event) => event.stopPropagation()}
      />
    ),
  }

  const table = useLegacyTable({
    data: rows,
    columns: [selectionColumn, ...columns],
    state: { sorting, columnVisibility, rowSelection },
    onSortingChange: setSorting,
    onColumnVisibilityChange: setColumnVisibility,
    onRowSelectionChange: setRowSelection,
    getCoreRowModel: getCoreRowModel(),
    getSortedRowModel: getSortedRowModel(),
    getRowId: (row) => row.id,
    enableRowSelection: true,
  })

  const selected = table.getSelectedRowModel().rows.map((row) => row.original)
  const visibleRows = table.getRowModel().rows.map((row) => row.original)
  const openIndex = visibleRows.findIndex((row) => row.id === openId)
  const openRow = openIndex >= 0 ? visibleRows[openIndex] : undefined

  function exportCsv(source: readonly T[]) {
    if (!csvColumns || !toCsvRow) return
    downloadCsv(csvFilename, toCsv(source.map(toCsvRow), csvColumns))
  }

  return (
    <div className={cn("flex flex-col gap-3", className)}>
      <div className="flex flex-col gap-3">
        {tabs && tabs.length > 0 ? (
          <div className="flex flex-wrap gap-1" role="tablist" aria-label={viewsLabel}>
            {tabs.map((item) => (
              <Button
                key={item.id}
                type="button"
                size="sm"
                role="tab"
                variant={tab === item.id ? "secondary" : "ghost"}
                aria-selected={tab === item.id}
                onClick={() => {
                  setTab(item.id)
                  setRowSelection({})
                }}
              >
                {item.label}
                <Badge variant="outline" className="tabular-nums">
                  {counts.get(item.id) ?? 0}
                </Badge>
              </Button>
            ))}
          </div>
        ) : null}
        <div className="flex flex-wrap items-center gap-2">
          <div className="relative min-w-40 flex-1 sm:max-w-xs">
            <Search className="pointer-events-none absolute top-1/2 left-2 size-4 -translate-y-1/2 text-muted-foreground" />
            <Input
              value={query}
              onChange={(event) => setQuery(event.target.value)}
              placeholder={searchPlaceholder}
              aria-label={searchPlaceholder}
              className="pl-8"
            />
          </div>
          {(filters ?? []).map((filter) => (
            <Select
              key={filter.id}
              value={filterValues[filter.id] ?? "any"}
              onValueChange={(value) =>
                setFilterValues((current) => ({ ...current, [filter.id]: value }))
              }
            >
              <SelectTrigger className="w-40" aria-label={filter.label}>
                <SelectValue placeholder={filter.label} />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="any">{filter.label}</SelectItem>
                {filter.options.map((option) => (
                  <SelectItem key={option.value} value={option.value}>
                    {option.label}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          ))}
          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <Button type="button" variant="outline" size="sm">
                <Columns3 />
                {columnsLabel}
              </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent align="end">
              <DropdownMenuLabel>{columnsLabel}</DropdownMenuLabel>
              {table
                .getAllLeafColumns()
                .filter((column) => column.getCanHide())
                .map((column) => (
                  <DropdownMenuCheckboxItem
                    key={column.id}
                    checked={column.getIsVisible()}
                    onCheckedChange={(value) => column.toggleVisibility(value === true)}
                  >
                    {typeof column.columnDef.header === "string" ? column.columnDef.header : column.id}
                  </DropdownMenuCheckboxItem>
                ))}
            </DropdownMenuContent>
          </DropdownMenu>
          {csvColumns ? (
            <Button
              type="button"
              variant="outline"
              size="sm"
              onClick={() => exportCsv(selected.length ? selected : visibleRows)}
            >
              <Download />
              {csvLabel}
            </Button>
          ) : null}
        </div>
        {selected.length > 0 && bulkActions && bulkActions.length > 0 ? (
          <div className="flex flex-wrap items-center gap-2 rounded-lg bg-muted px-3 py-2 text-sm">
            <span className="tabular-nums">
              {selected.length} {selectedLabel}
            </span>
            {bulkActions.map((action) => (
              <Button
                key={action.id}
                type="button"
                size="sm"
                variant={action.destructive ? "destructive" : "secondary"}
                disabled={acting != null}
                onClick={() => {
                  setActing(action.id)
                  void (async () => {
                    try {
                      await action.onAction(selected)
                      setRowSelection({})
                    } catch (error) {
                      toast.error(error instanceof Error && error.message ? error.message : actionErrorLabel)
                    } finally {
                      setActing(null)
                    }
                  })()
                }}
              >
                {action.label}
              </Button>
            ))}
          </div>
        ) : null}
      </div>

      <div className="overflow-x-auto rounded-xl ring-1 ring-foreground/10">
        <Table>
          <TableHeader>
            {table.getHeaderGroups().map((group) => (
              <TableRow key={group.id}>
                {group.headers.map((header) => {
                  const sorted = header.column.getIsSorted()
                  return (
                    <TableHead key={header.id}>
                      {header.isPlaceholder ? null : header.column.getCanSort() ? (
                        <button
                          type="button"
                          className="inline-flex items-center gap-1"
                          onClick={header.column.getToggleSortingHandler()}
                        >
                          {flexRender(header.column.columnDef.header, header.getContext())}
                          {sorted === "asc" ? (
                            <ArrowUp className="size-3" />
                          ) : sorted === "desc" ? (
                            <ArrowDown className="size-3" />
                          ) : (
                            <ArrowUpDown className="size-3 opacity-40" />
                          )}
                        </button>
                      ) : (
                        flexRender(header.column.columnDef.header, header.getContext())
                      )}
                    </TableHead>
                  )
                })}
              </TableRow>
            ))}
          </TableHeader>
          <TableBody>
            {table.getRowModel().rows.length === 0 ? (
              <TableRow>
                <TableCell colSpan={table.getVisibleLeafColumns().length}>
                  <EmptyState title={emptyTitle} />
                </TableCell>
              </TableRow>
            ) : (
              table.getRowModel().rows.map((row) => (
                <TableRow
                  key={row.id}
                  data-state={row.getIsSelected() ? "selected" : undefined}
                  className={renderDetail ? "cursor-pointer" : undefined}
                  tabIndex={renderDetail ? 0 : undefined}
                  onClick={() => {
                    if (renderDetail) setOpenId(row.original.id)
                  }}
                  onKeyDown={(event) => {
                    if (!renderDetail) return
                    if (event.target !== event.currentTarget) return
                    if (event.key === "Enter" || event.key === " ") {
                      event.preventDefault()
                      setOpenId(row.original.id)
                    }
                  }}
                >
                  {row.getVisibleCells().map((cell) => (
                    <TableCell key={cell.id}>
                      {flexRender(cell.column.columnDef.cell, cell.getContext())}
                    </TableCell>
                  ))}
                </TableRow>
              ))
            )}
          </TableBody>
        </Table>
      </div>

      {renderDetail ? (
        <Sheet open={openRow != null} onOpenChange={(open) => !open && setOpenId(null)}>
          <SheetContent className="w-full overflow-y-auto sm:max-w-md">
            <SheetHeader>
              <SheetTitle>{openRow ? (detailTitle?.(openRow) ?? detailFallback) : detailFallback}</SheetTitle>
              <SheetDescription className="sr-only">{detailDescription}</SheetDescription>
            </SheetHeader>
            <div className="flex items-center gap-2 px-4">
              <Button
                type="button"
                size="sm"
                variant="outline"
                disabled={openIndex <= 0}
                onClick={() => {
                  const prev = visibleRows[openIndex - 1]
                  if (prev) setOpenId(prev.id)
                }}
              >
                {previousLabel}
              </Button>
              <Button
                type="button"
                size="sm"
                variant="outline"
                disabled={openIndex < 0 || openIndex >= visibleRows.length - 1}
                onClick={() => {
                  const next = visibleRows[openIndex + 1]
                  if (next) setOpenId(next.id)
                }}
              >
                {nextLabel}
              </Button>
            </div>
            <div className="px-4 pb-6">{openRow ? renderDetail(openRow) : null}</div>
          </SheetContent>
        </Sheet>
      ) : null}
    </div>
  )
}

"use client"

import * as React from "react"
import { ChevronDown, Inbox } from "lucide-react"
import { toast } from "sonner"

import { cn } from "@/lib/utils"
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog"
import { Button } from "@/components/ui/button"
import { Collapsible, CollapsibleContent, CollapsibleTrigger } from "@/components/ui/collapsible"
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog"
import {
  Sheet,
  SheetContent,
  SheetDescription,
  SheetFooter,
  SheetHeader,
  SheetTitle,
} from "@/components/ui/sheet"

export type EntityFormProps = {
  open: boolean
  onOpenChange: (open: boolean) => void
  title: string
  description?: string
  presentation?: "dialog" | "sheet"
  onSubmit: (formData: FormData) => Promise<void> | void
  onDelete?: () => Promise<void> | void
  submitLabel?: string
  cancelLabel?: string
  deleteLabel?: string
  pendingLabel?: string
  /** Shown when onSubmit or onDelete rejects and onError is omitted. */
  errorLabel?: string
  onError?: (error: unknown) => void
  busy?: boolean
  children?: React.ReactNode
  className?: string
}

/**
 * Create or edit one record in a dialog or a sheet.
 *
 * Position is not part of the form. The parent should pass the existing
 * `position` through `keepPosition` so a save does not send the row to the end.
 * While `busy` is true (an upload, for example) submit stays disabled.
 */
export function EntityForm({
  open,
  onOpenChange,
  title,
  description,
  presentation = "dialog",
  onSubmit,
  onDelete,
  submitLabel = "Save",
  cancelLabel = "Cancel",
  deleteLabel = "Delete",
  pendingLabel = "Saving…",
  errorLabel = "Could not save",
  onError,
  busy = false,
  children,
  className,
}: EntityFormProps) {
  const [pending, setPending] = React.useState(false)
  const [confirmOpen, setConfirmOpen] = React.useState(false)
  const locked = busy || pending

  async function handleSubmit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault()
    if (locked) return
    const formData = new FormData(event.currentTarget)
    setPending(true)
    try {
      await onSubmit(formData)
      onOpenChange(false)
    } catch (error) {
      if (onError) onError(error)
      else toast.error(error instanceof Error && error.message ? error.message : errorLabel)
    } finally {
      setPending(false)
    }
  }

  const form = (
    <form className="flex min-h-0 flex-1 flex-col gap-4" onSubmit={handleSubmit}>
      <div className={cn("flex flex-col gap-3", className)}>{children}</div>
      <div className="mt-auto flex flex-wrap items-center gap-2">
        {onDelete ? (
          <Button type="button" variant="destructive" onClick={() => setConfirmOpen(true)} disabled={locked}>
            {deleteLabel}
          </Button>
        ) : null}
        <div className="ml-auto flex gap-2">
          <Button type="button" variant="outline" onClick={() => onOpenChange(false)} disabled={locked}>
            {cancelLabel}
          </Button>
          <Button type="submit" disabled={locked}>
            {pending ? pendingLabel : submitLabel}
          </Button>
        </div>
      </div>
    </form>
  )

  return (
    <>
      {presentation === "sheet" ? (
        <Sheet open={open} onOpenChange={onOpenChange}>
          <SheetContent className="flex w-full flex-col sm:max-w-md" side="right">
            <SheetHeader>
              <SheetTitle>{title}</SheetTitle>
              {description ? <SheetDescription>{description}</SheetDescription> : null}
            </SheetHeader>
            {form}
            <SheetFooter className="hidden" />
          </SheetContent>
        </Sheet>
      ) : (
        <Dialog open={open} onOpenChange={onOpenChange}>
          <DialogContent className="flex max-h-[85vh] flex-col sm:max-w-lg">
            <DialogHeader>
              <DialogTitle>{title}</DialogTitle>
              {description ? <DialogDescription>{description}</DialogDescription> : null}
            </DialogHeader>
            <div className="min-h-0 overflow-y-auto">{form}</div>
            <DialogFooter className="hidden" />
          </DialogContent>
        </Dialog>
      )}
      {onDelete ? (
        <ConfirmDelete
          open={confirmOpen}
          onOpenChange={setConfirmOpen}
          title={deleteLabel}
          description={description ?? title}
          confirmLabel={deleteLabel}
          cancelLabel={cancelLabel}
          errorLabel={errorLabel}
          onError={onError}
          onConfirm={async () => {
            await onDelete()
            setConfirmOpen(false)
            onOpenChange(false)
          }}
        />
      ) : null}
    </>
  )
}

export type ConfirmDeleteProps = {
  open: boolean
  onOpenChange: (open: boolean) => void
  title?: string
  description?: string
  confirmLabel?: string
  cancelLabel?: string
  errorLabel?: string
  onError?: (error: unknown) => void
  onConfirm: () => Promise<void> | void
}

export function ConfirmDelete({
  open,
  onOpenChange,
  title = "Delete",
  description = "This cannot be undone.",
  confirmLabel = "Delete",
  cancelLabel = "Cancel",
  errorLabel = "Could not delete",
  onError,
  onConfirm,
}: ConfirmDeleteProps) {
  const [pending, setPending] = React.useState(false)
  return (
    <AlertDialog open={open} onOpenChange={onOpenChange}>
      <AlertDialogContent>
        <AlertDialogHeader>
          <AlertDialogTitle>{title}</AlertDialogTitle>
          <AlertDialogDescription>{description}</AlertDialogDescription>
        </AlertDialogHeader>
        <AlertDialogFooter>
          <AlertDialogCancel disabled={pending}>{cancelLabel}</AlertDialogCancel>
          <AlertDialogAction
            variant="destructive"
            disabled={pending}
            onClick={(event) => {
              event.preventDefault()
              setPending(true)
              void (async () => {
                try {
                  await onConfirm()
                } catch (error) {
                  if (onError) onError(error)
                  else toast.error(error instanceof Error && error.message ? error.message : errorLabel)
                } finally {
                  setPending(false)
                }
              })()
            }}
          >
            {confirmLabel}
          </AlertDialogAction>
        </AlertDialogFooter>
      </AlertDialogContent>
    </AlertDialog>
  )
}

export function EmptyState({
  title,
  description,
  action,
  className,
}: {
  title: string
  description?: string
  action?: React.ReactNode
  className?: string
}) {
  return (
    <div
      className={cn(
        "flex flex-col items-center justify-center gap-2 rounded-xl border border-dashed border-border px-6 py-10 text-center",
        className,
      )}
    >
      <Inbox className="size-5 text-muted-foreground" />
      <p className="text-sm font-medium">{title}</p>
      {description ? <p className="max-w-sm text-sm text-muted-foreground">{description}</p> : null}
      {action}
    </div>
  )
}

export function AdminSection({
  title,
  description,
  defaultOpen = true,
  children,
  className,
}: {
  title: string
  description?: string
  defaultOpen?: boolean
  children?: React.ReactNode
  className?: string
}) {
  return (
    <Collapsible defaultOpen={defaultOpen} className={cn("rounded-xl bg-card ring-1 ring-foreground/10", className)}>
      <CollapsibleTrigger className="flex w-full items-center gap-2 px-4 py-3 text-left">
        <span className="min-w-0 flex-1">
          <span className="block text-sm font-medium">{title}</span>
          {description ? <span className="block text-xs text-muted-foreground">{description}</span> : null}
        </span>
        <ChevronDown className="size-4 text-muted-foreground transition-transform in-data-[state=open]:rotate-180 motion-reduce:transition-none" />
      </CollapsibleTrigger>
      <CollapsibleContent className="flex flex-col gap-3 px-4 pb-4">{children}</CollapsibleContent>
    </Collapsible>
  )
}

export type CsvColumn = {
  key: string
  header: string
}

export function escapeCsvCell(value: unknown): string {
  if (value == null) return ""
  let text = String(value)
  // Spreadsheets treat a leading = + - @ tab or line break as a formula.
  if (typeof value === "string" && /^[=+\-@\t\r\n]/.test(text)) text = `'${text}`
  if (/[",\n\r']/.test(text)) return `"${text.replace(/"/g, '""')}"`
  return text
}

export function toCsv(
  rows: readonly Record<string, unknown>[],
  columns: readonly CsvColumn[],
): string {
  const head = columns.map((column) => escapeCsvCell(column.header)).join(",")
  const body = rows
    .map((row) => columns.map((column) => escapeCsvCell(row[column.key])).join(","))
    .join("\n")
  return body ? `${head}\n${body}` : head
}

export function downloadCsv(filename: string, csv: string) {
  if (typeof document === "undefined") return
  const blob = new Blob([csv], { type: "text/csv;charset=utf-8" })
  const url = URL.createObjectURL(blob)
  const link = document.createElement("a")
  link.href = url
  link.download = filename.endsWith(".csv") ? filename : `${filename}.csv`
  link.click()
  URL.revokeObjectURL(url)
}
